// HLS ap_int stub header

#ifndef AP_INT_H_
#define AP_INT_H_

#include <cstdint>
#include <type_traits>
#include <cstdio>

// Stub for ap_int (signed arbitrary precision integer)
template <int W>
struct ap_int {
    using storage_type = typename std::conditional<
        (W <= 8), int8_t,
        typename std::conditional<
            (W <= 16), int16_t,
            typename std::conditional<
                (W <= 32), int32_t,
                int64_t
            >::type
        >::type
    >::type;

    storage_type val;

    ap_int() : val(0) {}
    ap_int(int v) : val(static_cast<storage_type>(v)) {}
    ap_int(long v) : val(static_cast<storage_type>(v)) {}
    ap_int(long long v) : val(static_cast<storage_type>(v)) {}

    ap_int& operator=(int v) { val = static_cast<storage_type>(v); return *this; }

    operator storage_type() const { return val; }

    // Range selection
    template <int H, int L>
    ap_int<H-L+1> range() const {
        return ap_int<H-L+1>((val >> L) & ((1LL << (H-L+1)) - 1));
    }

    // Bit access
    bool operator[](int idx) const {
        return (val >> idx) & 1;
    }
};

// Stub for ap_uint (unsigned arbitrary precision integer)
template <int W>
struct ap_uint {
    using storage_type = typename std::conditional<
        (W <= 8), uint8_t,
        typename std::conditional<
            (W <= 16), uint16_t,
            typename std::conditional<
                (W <= 32), uint32_t,
                uint64_t
            >::type
        >::type
    >::type;

    storage_type val;

    ap_uint() : val(0) {}
    ap_uint(unsigned int v) : val(static_cast<storage_type>(v)) {}
    ap_uint(unsigned long v) : val(static_cast<storage_type>(v)) {}
    ap_uint(unsigned long long v) : val(static_cast<storage_type>(v)) {}
    ap_uint(int v) : val(static_cast<storage_type>(v)) {}

    ap_uint& operator=(unsigned int v) { val = static_cast<storage_type>(v); return *this; }

    operator storage_type() const { return val; }

    // Range selection
    template <int H, int L>
    ap_uint<H-L+1> range() const {
        return ap_uint<H-L+1>((val >> L) & ((1ULL << (H-L+1)) - 1));
    }

    // Bit access
    bool operator[](int idx) const {
        return (val >> idx) & 1;
    }

    // Bitwise operations
    ap_uint operator()(int H, int L) const {
        return ap_uint((val >> L) & ((1ULL << (H-L+1)) - 1));
    }
};

#endif // AP_INT_H_
