// TAPA HLS Stub Header

#ifndef TAPA_H_
#define TAPA_H_

#include <cstddef>
#include <cstdint>

namespace tapa {

// TAPA memory map type
template <typename T>
struct mmap {
    T* data;
    mmap() : data(nullptr) {}
    explicit mmap(T* d) : data(d) {}

    T& operator[](size_t idx) { return data[idx]; }
    const T& operator[](size_t idx) const { return data[idx]; }
};

// TAPA async memory map type
template <typename T>
struct async_mmap {
    struct read_addr_type {
        bool try_write(size_t addr) { return true; }
    };
    struct read_data_type {
        bool empty() { return false; }
        T read(bool* success) { return T(); }
    };
    struct write_addr_type {
        bool full() { return false; }
        bool try_write(size_t addr) { return true; }
    };
    struct write_data_type {
        bool full() { return false; }
        bool try_write(const T& val) { return true; }
    };
    struct write_resp_type {
        bool empty() { return false; }
        int read(bool* success) { return 0; }
    };

    read_addr_type read_addr;
    read_data_type read_data;
    write_addr_type write_addr;
    write_data_type write_data;
    write_resp_type write_resp;
};

// TAPA stream types
template <typename T>
struct istream {
    bool empty() { return false; }
    T read() { return T(); }
};

template <typename T>
struct ostream {
    bool full() { return false; }
    void write(const T& val) {}
};

template <typename T, int N>
struct istreams {
    istream<T> streams[N];
    bool empty() { return false; }
    T read() { return T(); }
    istream<T>& operator[](int idx) { return streams[idx]; }
};

template <typename T, int N>
struct ostreams {
    ostream<T> streams[N];
    bool full() { return false; }
    void write(const T& val) {}
    ostream<T>& operator[](int idx) { return streams[idx]; }
};

// TAPA streams with depth
template <typename T, int N, int Depth = 2>
struct streams {
    T data[N][Depth];
    int head[N];
    int tail[N];

    streams() {
        for (int i = 0; i < N; i++) {
            head[i] = 0;
            tail[i] = 0;
        }
    }

    T& operator()(int idx, int) {
        return data[idx][head[idx]];
    }
};

// TAPA task for chaining
struct task {
    template <typename Func, typename... Args>
    task& invoke(Func&& f, Args&&... args) {
        return *this;
    }

    template <typename Func, typename... Args>
    task& invoke(Func&& f, int id0, int id1, Args&&... args) {
        return *this;
    }
};

} // namespace tapa

#endif // TAPA_H_
